var t=`0041-kluski-slaskie`;var n=`world-0041`;var s=`PL`;var o=`eastern-europe`;var a=4;var l=59;var r={en:`Kluski Śląskie`,ua:`Сілезькі кльоцки`};var g={en:`A classic dish from Poland, featuring potato, chicken egg, potato starch, unsalted butter. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Польща. Основні складники: картопля, куряче яйце, картопляний крохмаль, несолоне вершкове масло. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var d=[{en:`Cook the listed ingredients in simmering water for about 30 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 30 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:30,i:[[`potato`,700,`g`],[`water`,1100,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`potato-starch`,180,`g`],[`chicken-egg`,1,`pcs`],[`table-salt`,3,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:9,i:[]},{en:`Cook dumplings in batches in gently boiling salted water for about 8 minutes, until they float and the filling is cooked through. Lift out with a slotted spoon.`,ua:`Варіть вироби порціями в ледь киплячій підсоленій воді приблизно 8 хвилин, доки вони спливуть і начинка приготується. Вийміть шумівкою.`,t:[`boiling`],m:8,i:[[`water`,1300,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`unsalted-butter`,45,`g`]]}];var u={slug:t,id:n,country:`PL`,region:o,servings:4,minutes:59,title:r,text:g,steps:d};export{s as country,u as default,n as id,l as minutes,o as region,a as servings,t as slug,d as steps,g as text,r as title};